```python
#!/usr/bin/env python3
"""
Indian income-tax calculator — Financial Year 2025-26 (Assessment Year 2026-27).

Reads the taxpayer's financial details from 'input.json' in the current working
directory, computes the complete tax computation and prints ONLY the resulting
JSON object on stdout.  Python standard library only.

Key rules implemented (FY 2025-26 / AY 2026-27):
  * New regime (Section 115BAC) slabs: 0-4L nil, 5% (4-8L), 10% (8-12L),
    15% (12-16L), 20% (16-20L), 25% (20-24L), 30% above 24L; standard
    deduction Rs.75,000; rebate u/s 87A up to Rs.60,000 for income <= 12L.
  * Old regime slabs: 0-2.5L nil, 5% (2.5-5L), 20% (5-10L), 30% above 10L;
    standard deduction Rs.50,000 (Rs.1,00,000 for age >= 60); rebate u/s 87A
    up to Rs.12,500 for income <= 5L.
  * HRA (10(13A)) / LTA (10(5)) exemptions: old regime only and not available
    where total income exceeds Rs.19,90,000.
  * STCG on listed equity/equity MF (s.111A) @20%; LTCG on listed equity/equity
    MF (s.112A) @12.5% above Rs.1,25,000; other LTCG at slab rates (20% where
    acquired on/after 23-Jul-2024 and held beyond 3 years).
  * Capital losses: set-off within the year, carry forward for 8 assessment
    years only (losses older than that are expired).
  * Surcharge (10/15/25/37%) with marginal relief, health & education cess 4%.
"""

import json
import os
import sys
from datetime import date, datetime

# --------------------------------------------------------------------- constants
CURRENT_FY = "2025-26"
CURRENT_FY_START_YEAR = 2025

NEW_REGIME_SLABS = (
    (400000.0, 0.00),
    (800000.0, 0.05),
    (1200000.0, 0.10),
    (1600000.0, 0.15),
    (2000000.0, 0.20),
    (2400000.0, 0.25),
    (None, 0.30),
)
OLD_REGIME_SLABS = (
    (250000.0, 0.00),
    (500000.0, 0.05),
    (1000000.0, 0.20),
    (None, 0.30),
)

STD_DEDUCTION_NEW = 75000.0
STD_DEDUCTION_OLD = 50000.0
STD_DEDUCTION_OLD_SENIOR = 100000.0

HRA_LTA_INCOME_CAP = 1990000.0        # 19.90 lakh ceiling for 10(13A)/10(5)
PROFESSIONAL_TAX_CAP = 2500.0
EMPLOYER_PF_16_III_CAP = 150000.0

CAP_80C = 150000.0
CAP_80CCC = 150000.0
CAP_80CCD1 = 50000.0
CAP_80CCD1B = 50000.0
CAP_80CCD2 = 50000.0
CAP_80D_SELF = 25000.0
CAP_80D_SENIOR = 50000.0
CAP_80TTA = 5000.0
CAP_80TTA_SENIOR = 10000.0
CAP_80TTB = 50000.0

STCG_111A_RATE = 0.20
LTCG_112A_RATE = 0.125
LTCG_112A_EXEMPTION = 125000.0
LTCG_NON_EQUITY_SPECIAL_RATE = 0.20
LTCG_SPECIAL_RATE_PURCHASE_DATE = date(2024, 7, 23)

CESS_RATE = 0.04
REBATE_NEW_LIMIT = 1200000.0
REBATE_NEW_MAX = 60000.0
REBATE_OLD_LIMIT = 500000.0
REBATE_OLD_MAX = 12500.0
REBATE_INCOME_CEILING = 10000000.0     # s.87A rebate not available above Rs.1 crore

SURCHARGE_BANDS = (
    (50000000.0, 100000000.0, 0.10),
    (100000000.0, 200000000.0, 0.15),
    (200000000.0, 500000000.0, 0.25),
    (500000000.0, None, 0.37),
)

SALARY_COMPONENTS = (
    "Basic Salary", "Dearness Allowance", "HRA", "Conveyance Allowance",
    "Medical Allowance", "Bonuses and Incentives", "Overtime Pay", "LTA",
    "Special Allowance", "Entertainment Allowance",
)

STCG_OTHER_KEYS = ("Bonds", "Debentures", "G-Secs", "Mutual Funds")
LTCG_NE_KEYS = ("Bonds", "Debentures", "G-Secs", "Mutual Funds")

# Funds eligible for 100% deduction under section 80G without qualifying limit.
FUNDS_100_PERCENT = {
    "pm cares fund", "pm cares", "national disaster relief fund", "ndrf",
    "prime minister national relief fund", "pmnrf", "national relief fund",
    "chief minister relief fund", "cmrf", "india covid 19 relief fund",
    "prime minister citizen relief and welfare fund", "national welfare fund",
}
# Funds eligible for 50% deduction under section 80G without qualifying limit.
FUNDS_50_PERCENT = {
    "prime minister drought relief fund", "pmdrf", "drought relief fund",
    "swachh bharat mission", "swachh bharat abhiyan", "national clean india fund",
    "prime minister national integration fund",
}


# ----------------------------------------------------------------------- helpers
def num(value):
    """Best-effort conversion of an input value to a float."""
    if isinstance(value, bool):
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    if value is None:
        return 0.0
    try:
        return float(str(value).replace(",", "").strip())
    except (TypeError, ValueError):
        return 0.0


def r2(value):
    """Round to two decimals (keeps the JSON output tidy)."""
    return round(num(value) + 0.0, 2)


def parse_date(value):
    if not value:
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%d-%m-%Y", "%d/%m/%Y", "%Y/%m/%d", "%m/%d/%Y", "%d-%b-%Y"):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            continue
    return None


def months_held(start, end):
    """Number of whole months between two dates (0 if either date is missing)."""
    if start is None or end is None:
        return 0
    months = (end.year - start.year) * 12 + (end.month - start.month)
    if end.day < start.day:
        months -= 1
    return months


def fy_start_year(fy):
    try:
        return int(str(fy).split("-")[0])
    except (ValueError, IndexError):
        return CURRENT_FY_START_YEAR


def loss_is_live(fy):
    """Capital losses may be carried forward for 8 assessment years only."""
    return (CURRENT_FY_START_YEAR - fy_start_year(fy)) <= 8


def normalise(text):
    cleaned = "".join(ch if ch.isalnum() or ch.isspace() else " " for ch in str(text).lower())
    return " ".join(cleaned.split())


def slab_tax(income, slabs):
    """Tax on `income` computed with the given slab structure."""
    income = num(income)
    if income <= 0:
        return 0.0
    tax = 0.0
    lower = 0.0
    for upper, rate in slabs:
        if upper is None or income <= upper:
            tax += (income - lower) * rate
            return tax
        tax += (upper - lower) * rate
        lower = upper
    return tax


def reduce_parts(parts, amount):
    """Reduce a list of (amount, special_rate) entries by `amount` (in order)."""
    remaining = max(0.0, num(amount))
    for index, (value, special) in enumerate(parts):
        if remaining <= 0:
            break
        if value <= remaining:
            remaining -= value
            parts[index] = (0.0, special)
        else:
            parts[index] = (value - remaining, special)
            remaining = 0.0
    return parts


# ------------------------------------------------------------------ salary block
def hra_exemption(data, salary, salary_base):
    hra = num(salary.get("HRA"))
    rent = num(data.get("Actual Rent Paid"))
    if hra <= 0 or rent <= 0:
        return 0.0
    city = str(data.get("City") or "non-metro").strip().lower()
    share = 0.50 if city == "metro" else 0.40
    return max(0.0, min(hra, rent - 0.10 * salary_base, share * salary_base))


def lta_exemption(data, salary, salary_base):
    lta = num(salary.get("LTA"))
    if lta <= 0:
        return 0.0
    city = str(data.get("City") or "non-metro").strip().lower()
    share = 0.05 if city == "metro" else 0.03
    claimed = num(data.get("LTA Travel Expenses Claimed"))
    return max(0.0, min(lta, claimed, share * salary_base))


def entertainment_exemption(data, salary):
    if str(data.get("Employment Type") or "private").strip().lower() != "government":
        return 0.0
    actual = num(salary.get("Entertainment Allowance"))
    if actual <= 0:
        return 0.0
    return max(0.0, min(actual / 3.0, 6000.0 * 12))


# --------------------------------------------------------------- capital gains
def compute_capital_gains(data):
    """Returns gross gains/losses per bucket before any set-off."""
    stcg_111a = 0.0
    stcg_other = {key: 0.0 for key in STCG_OTHER_KEYS}
    stcg_other_extra = 0.0
    ltcg_112a = 0.0
    ltcg_non_equity = {key: 0.0 for key in LTCG_NE_KEYS}
    ltcg_non_equity_parts = {key: [] for key in LTCG_NE_KEYS}
    ltcg_other = 0.0

    # ---- listed / unlisted shares -------------------------------------------
    for tx in data.get("Stock Sale Transactions") or []:
        sale_price = num(tx.get("Sale Price"))
        cost_price = num(tx.get("Cost Price"))
        quantity = num(tx.get("Quantity"))
        brokerage = num(tx.get("Brokerage"))
        stt = num(tx.get("STT"))
        purchase = parse_date(tx.get("Purchase Date"))
        sale_date = parse_date(tx.get("Sale Date"))
        fmv = num(tx.get("FMV as of 31 Jan 2018"))

        # Shares acquired before 01-Feb-2018: cost is the higher of cost and FMV.
        if purchase is not None and purchase < date(2018, 2, 1) and fmv > cost_price:
            cost_price = fmv

        gain = (sale_price - cost_price) * quantity - brokerage - stt
        held = months_held(purchase, sale_date)
        listed_equity = stt > 0

        if held > 12:
            if listed_equity:
                ltcg_112a += gain
            else:
                ltcg_other += gain
        else:
            if listed_equity:
                stcg_111a += gain
            else:
                stcg_other_extra += gain

    # ---- mutual funds --------------------------------------------------------
    for tx in data.get("Mutual Fund Transactions") or []:
        gain = num(tx.get("Sale Value")) - num(tx.get("Purchase Value"))
        purchase = parse_date(tx.get("Purchase Date"))
        sale_date = parse_date(tx.get("Sale Date"))
        held = months_held(purchase, sale_date)
        mf_type = str(tx.get("Type") or "").strip().lower()

        if mf_type in ("equity", "elss", "hybrid-equity"):
            if held > 12:
                ltcg_112a += gain
            else:
                stcg_111a += gain
        else:
            threshold = 24 if mf_type in ("gold-etf", "gold-mf") else 12
            if held > threshold:
                ltcg_non_equity["Mutual Funds"] += gain
                special = (purchase is not None
                           and purchase >= LTCG_SPECIAL_RATE_PURCHASE_DATE
                           and held > 36)
                ltcg_non_equity_parts["Mutual Funds"].append((gain, special))
            else:
                stcg_other["Mutual Funds"] += gain

    # ---- bonds, debentures and G-Secs ---------------------------------------
    for key in ("Bonds", "Debentures", "G-Secs"):
        asset = data.get(key) or {}
        gain = num(asset.get("Sale Amount")) - num(asset.get("Purchase Amount"))
        years = num(asset.get("Held for duration in years"))
        if gain == 0:
            continue
        if years > 3:
            ltcg_non_equity[key] += gain
            # Purchase date is not supplied for these assets, so the 20% rate
            # (post 23-Jul-2024 acquisitions) cannot be applied.
            ltcg_non_equity_parts[key].append((gain, False))
        else:
            stcg_other[key] += gain

    # ---- privately owned vehicle (movable property: LTCG beyond 24 months) ---
    vehicle = data.get("Privately Owned Vehicle") or {}
    vehicle_gain = num(vehicle.get("Sale Amount")) - num(vehicle.get("Purchase Amount"))
    vehicle_years = num(vehicle.get("Held for duration in years"))
    if vehicle_gain != 0:
        if vehicle_years > 2:
            ltcg_other += vehicle_gain
        else:
            stcg_other_extra += vehicle_gain

    return {
        "stcg_111a": stcg_111a,
        "stcg_other": stcg_other,
        "stcg_other_extra": stcg_other_extra,
        "ltcg_112a": ltcg_112a,
        "ltcg_non_equity": ltcg_non_equity,
        "ltcg_non_equity_parts": ltcg_non_equity_parts,
        "ltcg_other": ltcg_other,
    }


def apply_capital_loss_setoff(cg, data):
    """Set off capital losses (including declared, still-live losses)."""
    stcg_111a = cg["stcg_111a"]
    stcg_other = dict(cg["stcg_other"])
    stcg_extra = cg["stcg_other_extra"]
    ltcg_112a = cg["ltcg_112a"]
    ltcg_non_equity = dict(cg["ltcg_non_equity"])
    ltcg_parts = {key: list(value) for key, value in cg["ltcg_non_equity_parts"].items()}
    ltcg_other = cg["ltcg_other"]

    stcg_pool = 0.0
    ltcg_pool = 0.0

    # Declared losses (only those within the 8-year carry-forward window).
    for entry in data.get("Short Term Capital Loss") or []:
        if loss_is_live(entry.get("Financial Year")):
            stcg_pool += num(entry.get("Loss Amount"))
    for entry in data.get("Long Term Capital Loss") or []:
        if loss_is_live(entry.get("Financial Year")):
            ltcg_pool += num(entry.get("Loss Amount"))

    # Losses already arising from the transactions computed above.
    if stcg_111a < 0:
        stcg_pool += -stcg_111a
        stcg_111a = 0.0
    if stcg_extra < 0:
        stcg_pool += -stcg_extra
        stcg_extra = 0.0
    for key in STCG_OTHER_KEYS:
        if stcg_other[key] < 0:
            stcg_pool += -stcg_other[key]
            stcg_other[key] = 0.0
    if ltcg_112a < 0:
        ltcg_pool += -ltcg_112a
        ltcg_112a = 0.0
    if ltcg_other < 0:
        ltcg_pool += -ltcg_other
        ltcg_other = 0.0
    for key in LTCG_NE_KEYS:
        if ltcg_non_equity[key] < 0:
            ltcg_pool += -ltcg_non_equity[key]
            ltcg_non_equity[key] = 0.0
            ltcg_parts[key] = [(0.0, special) for _, special in ltcg_parts[key]]

    # ---- short-term loss set-off -------------------------------------------
    if stcg_pool > 0 and stcg_111a > 0:
        used = min(stcg_pool, stcg_111a)
        stcg_111a -= used
        stcg_pool -= used
    for key in STCG_OTHER_KEYS:
        if stcg_pool <= 0:
            break
        if stcg_other[key] > 0:
            used = min(stcg_pool, stcg_other[key])
            stcg_other[key] -= used
            stcg_pool -= used
    if stcg_pool > 0 and stcg_extra > 0:
        used = min(stcg_pool, stcg_extra)
        stcg_extra -= used
        stcg_pool -= used
    if stcg_pool > 0 and ltcg_112a > 0:
        used = min(stcg_pool, ltcg_112a)
        ltcg_112a -= used
        stcg_pool -= used
    for key in LTCG_NE_KEYS:
        if stcg_pool <= 0:
            break
        if ltcg_non_equity[key] > 0:
            used = min(stcg_pool, ltcg_non_equity[key])
            ltcg_non_equity[key] -= used
            reduce_parts(ltcg_parts[key], used)
            stcg_pool -= used
    if stcg_pool > 0 and ltcg_other > 0:
        used = min(stcg_pool, ltcg_other)
        ltcg_other -= used
        stcg_pool -= used

    # ---- long-term loss set-off (long-term gains only) ----------------------
    if ltcg_pool > 0 and ltcg_112a > 0:
        used = min(ltcg_pool, ltcg_112a)
        ltcg_112a -= used
        ltcg_pool -= used
    for key in LTCG_NE_KEYS:
        if ltcg_pool <= 0:
            break
        if ltcg_non_equity[key] > 0:
            used = min(ltcg_pool, ltcg_non_equity[key])
            ltcg_non_equity[key] -= used
            reduce_parts(ltcg_parts[key], used)
            ltcg_pool -= used
    if ltcg_pool > 0 and ltcg_other > 0:
        used = min(ltcg_pool, ltcg_other)
        ltcg_other -= used
        ltcg_pool -= used

    # Any residual loss is carried forward to future years (no current benefit).

    return {
        "stcg_111a": stcg_111a,
        "stcg_other": stcg_other,
        "stcg_other_extra": stcg_extra,
        "stcg_other_total": sum(stcg_other.values()) + stcg_extra,
        "ltcg_112a": ltcg_112a,
        "ltcg_non_equity": ltcg_non_equity,
        "ltcg_non_equity_parts": ltcg_parts,
        "ltcg_non_equity_total": sum(ltcg_non_equity.values()),
        "ltcg_other": ltcg_other,
    }


# ------------------------------------------------------------------- deductions
def compute_80d(data, age, regime):
    total = 0.0
    senior = age >= 60
    for policy in data.get("Health Insurance") or []:
        paid_by = str(policy.get("Paid By") or "").strip().lower()
        if paid_by != "self":
            continue                       # employer group cover: no deduction
        mode = str(policy.get("Payment Mode") or "").strip().lower()
        if mode == "cash":
            continue                       # cash premiums are not deductible
        amount = num(policy.get("Amount"))
        years = num(policy.get("Number of Years Paid")) or 1.0
        if years > 1:
            amount = amount / years        # premium covers several years
        beneficiary = str(policy.get("Beneficiary") or "self").strip().lower()
        if beneficiary in ("self", "spouse", "children", "family"):
            if senior:
                cap = CAP_80D_SENIOR
            else:
                cap = None if regime == "new" else CAP_80D_SELF
        else:
            cap = CAP_80D_SENIOR if senior else CAP_80D_SELF
        total += amount if cap is None else min(amount, cap)
    return total


def compute_80g(data, gross_total_income):
    total = 0.0
    for donation in data.get("Donations") or []:
        mode = str(donation.get("Mode") or "").strip().lower()
        if mode == "cash":
            continue                       # cash donations are not deductible
        amount = num(donation.get("Amount"))
        if amount <= 0:
            continue
        scheme = normalise(donation.get("Scheme Name"))
        if scheme in FUNDS_100_PERCENT:
            total += amount
        elif scheme in FUNDS_50_PERCENT:
            total += 0.50 * amount
        else:
            total += 0.50 * amount          # 50% subject to qualifying limit
    # Overall limit: 50% of the gross total income.
    if gross_total_income > 0:
        total = min(total, 0.50 * gross_total_income)
    return total


# ------------------------------------------------------------------ tax engine
def compute_surcharge(tax_after_rebate, income, regime, pre_surcharge_tax_fn):
    if tax_after_rebate <= 0 or income <= 50000000.0:
        return 0.0
    rate = 0.10
    threshold = 50000000.0
    for lower, upper, band_rate in SURCHARGE_BANDS:
        if upper is None or income <= upper:
            rate = band_rate
            threshold = lower
            break
    surcharge = tax_after_rebate * rate
    if regime == "new" and rate == 0.10:
        # New regime: 10% surcharge capped at 1.5% of income above Rs.50 lakh.
        surcharge = min(surcharge, 0.015 * (income - 50000000.0))
    # Marginal relief at the slab thresholds.
    if income > threshold:
        max_allowed = pre_surcharge_tax_fn(threshold) + (income - threshold) * rate
        if tax_after_rebate + surcharge > max_allowed:
            surcharge = max(0.0, max_allowed - tax_after_rebate)
    return surcharge


def build_output(data, hra_exempt, lta_exempt):
    regime = str(data.get("Tax Regime") or "new").strip().lower()
    if regime not in ("old", "new"):
        regime = "new"
    age = num(data.get("Age"))
    senior = age >= 60
    slabs = NEW_REGIME_SLABS if regime == "new" else OLD_REGIME_SLABS

    salary = data.get("Gross Salary") or {}
    gross_salary = sum(num(salary.get(c)) for c in SALARY_COMPONENTS)
    salary_base = num(salary.get("Basic Salary")) + num(salary.get("Dearness Allowance"))

    # ---- section 16 ---------------------------------------------------------
    sec16ia = min(num(data.get("Professional Tax")), PROFESSIONAL_TAX_CAP) \
        if regime == "old" else 0.0
    sec16ii = entertainment_exemption(data, salary)
    epf = data.get("EPF") or {}
    employer_pf = num(epf.get("Employer Contribution"))
    sec16iii = min(employer_pf, EMPLOYER_PF_16_III_CAP) if regime == "old" else 0.0

    if regime == "new":
        standard_deduction = STD_DEDUCTION_NEW
    else:
        standard_deduction = STD_DEDUCTION_OLD_SENIOR if senior else STD_DEDUCTION_OLD

    net_salary = (gross_salary - hra_exempt - lta_exempt - sec16ia - sec16ii
                  - sec16iii - standard_deduction)

    # ---- capital gains ------------------------------------------------------
    cg = compute_capital_gains(data)
    cg = apply_capital_loss_setoff(cg, data)

    # ---- income from other sources -----------------------------------------
    savings_interest = num(data.get("Savings Bank Interest"))
    deposit_interest = num(data.get("Deposit Interest"))
    other_interest = num(data.get("Other Interest"))
    epf_interest = num(data.get("EPF Taxable Interest"))

    gross_total_income = (net_salary + cg["stcg_111a"] + cg["stcg_other_total"]
                           + cg["ltcg_112a"] + cg["ltcg_non_equity_total"]
                           + cg["ltcg_other"] + savings_interest + deposit_interest
                           + other_interest + epf_interest)

    # ---- deductions ---------------------------------------------------------
    epf_employee = epf.get("Employee Contribution") or {}
    sec80c = min(
        num(data.get("PPF"))
        + num(epf_employee.get("Deducted from Salary"))
        + num(epf_employee.get("Voluntary"))
        + num(data.get("ELSS"))
        + num(data.get("NSC"))
        + num(data.get("Sukanya Samriddhi Yojana"))
        + num(data.get("SCSS")),
        CAP_80C)

    pension = data.get("Pension Scheme Premium") or {}
    pension_amount = num(pension.get("Amount"))
    pension_years = num(pension.get("Number of Years Paid")) or 1.0
    sec80ccc = min(pension_amount * pension_years, CAP_80CCC) if regime == "old" else 0.0

    nps = data.get("NPS") or {}
    nps_self = num(nps.get("Tier-1 Self Contribution"))
    nps_employer = num(nps.get("Tier-1 Employer Contribution"))
    sec80ccd1 = min(nps_self, CAP_80CCD1) if regime == "old" else 0.0
    sec80ccd1b = min(nps_self + nps_employer, CAP_80CCD1B)
    sec80ccd2 = min(nps_employer, CAP_80CCD2) if regime == "old" else 0.0

    sec80d = compute_80d(data, age, regime)

    education = data.get("Education Loan Interest") or {}
    edu_interest = num(education.get("Interest Paid"))
    edu_year = num(education.get("Year of Repayment"))
    sec80e = edu_interest if 1 <= edu_year <= 8 else 0.0

    sec80g = compute_80g(data, gross_total_income)

    sec80tta = 0.0
    sec80ttb = 0.0
    if regime == "old":
        sec80tta = min(savings_interest, CAP_80TTA_SENIOR if senior else CAP_80TTA)
        if senior:
            sec80ttb = min(deposit_interest, CAP_80TTB)

    total_deductions = (sec80c + sec80ccc + sec80ccd1 + sec80ccd1b + sec80ccd2
                        + sec80d + sec80e + sec80g + sec80tta + sec80ttb)

    total_taxable_income = max(0.0, gross_total_income - total_deductions)

    # ---- tax computation ----------------------------------------------------
    stcg_111a_gain = max(0.0, cg["stcg_111a"])
    ltcg_112a_gain = max(0.0, cg["ltcg_112a"])
    stcg_other_gain = max(0.0, cg["stcg_other_total"])
    ltcg_non_equity_gain = max(0.0, cg["ltcg_non_equity_total"])
    ltcg_other_gain = max(0.0, cg["ltcg_other"])

    # Income taxed at slab rates (special-rate incomes are excluded).
    slab_income = (total_taxable_income - stcg_111a_gain - ltcg_112a_gain
                   - stcg_other_gain - ltcg_non_equity_gain - ltcg_other_gain)
    slab_income = max(0.0, slab_income)

    tax_slab = slab_tax(slab_income, slabs)
    tax_stcg_111a = STCG_111A_RATE * stcg_111a_gain
    tax_stcg_other = slab_tax(stcg_other_gain, slabs)
    tax_ltcg_112a = LTCG_112A_RATE * max(0.0, ltcg_112a_gain - LTCG_112A_EXEMPTION)

    # LTCG (non-equity): 20% where acquired on/after 23-Jul-2024 and held > 3
    # years, otherwise at slab rates.
    special_total = 0.0
    normal_total = 0.0
    for key in LTCG_NE_KEYS:
        for amount, special in cg["ltcg_non_equity_parts"].get(key, []):
            if special:
                special_total += amount
            else:
                normal_total += amount
    tax_ltcg_non_equity = (LTCG_NON_EQUITY_SPECIAL_RATE * special_total
                           + slab_tax(normal_total, slabs))
    tax_ltcg_other = slab_tax(ltcg_other_gain, slabs)

    total_tax_before_rebate = (tax_slab + tax_stcg_111a + tax_stcg_other
                                + tax_ltcg_112a + tax_ltcg_non_equity + tax_ltcg_other)

    # ---- rebate under section 87A ------------------------------------------
    if regime == "new":
        limit, max_rebate = REBATE_NEW_LIMIT, REBATE_NEW_MAX
    else:
        limit, max_rebate = REBATE_OLD_LIMIT, REBATE_OLD_MAX
    rebate = 0.0
    if total_tax_before_rebate > 0 and total_taxable_income <= REBATE_INCOME_CEILING:
        if total_taxable_income <= limit:
            rebate = min(total_tax_before_rebate, max_rebate)
        else:
            # Marginal relief: rebate equals the excess of income over the
            # threshold, capped at the maximum rebate and at the tax payable.
            excess = total_taxable_income - limit
            if excess < total_tax_before_rebate:
                rebate = min(excess, max_rebate, total_tax_before_rebate)
    tax_after_rebate = max(0.0, total_tax_before_rebate - rebate)

    # ---- surcharge and cess -------------------------------------------------
    special_taxes = tax_stcg_111a + tax_stcg_other + tax_ltcg_112a \
        + tax_ltcg_non_equity + tax_ltcg_other

    def pre_surcharge_tax(income_value):
        base = max(0.0, slab_income + (income_value - total_taxable_income))
        return slab_tax(base, slabs) + special_taxes

    surcharge = compute_surcharge(tax_after_rebate, total_taxable_income, regime,
                                  pre_surcharge_tax)
    cess = CESS_RATE * (tax_after_rebate + surcharge)
    total_tax_liability = tax_after_rebate + surcharge + cess

    tds = num(data.get("TDS"))
    net_payable = total_tax_liability - tds

    return {
        "Under Head Salaries": {
            "Gross Salary": r2(gross_salary),
            "Exemptions": {
                "Section 10(13A)": r2(hra_exempt),
                "Section 10(5)": r2(lta_exempt),
            },
            "Section 16(ia)": r2(sec16ia),
            "Section 16(ii)": r2(sec16ii),
            "Section 16(iii)": r2(sec16iii),
            "Net Salary": r2(net_salary),
        },
        "Capital Gains": {
            "STCG (Section 111A)": r2(cg["stcg_111a"]),
            "STCG (Other)": {
                "Bonds": r2(cg["stcg_other"]["Bonds"]),
                "Debentures": r2(cg["stcg_other"]["Debentures"]),
                "G-Secs": r2(cg["stcg_other"]["G-Secs"]),
                "Mutual Funds": r2(cg["stcg_other"]["Mutual Funds"]),
                "Total": r2(cg["stcg_other_total"]),
            },
            "LTCG (Section 112A)": r2(cg["ltcg_112a"]),
            "LTCG (Non-Equity)": {
                "Bonds": r2(cg["ltcg_non_equity"]["Bonds"]),
                "Debentures": r2(cg["ltcg_non_equity"]["Debentures"]),
                "G-Secs": r2(cg["ltcg_non_equity"]["G-Secs"]),
                "Mutual Funds": r2(cg["ltcg_non_equity"]["Mutual Funds"]),
                "Total": r2(cg["ltcg_non_equity_total"]),
            },
            "LTCG (Other)": r2(cg["ltcg_other"]),
        },
        "Income from Other Sources": {
            "Savings Bank Interest": r2(savings_interest),
            "Deposit Interest": r2(deposit_interest),
            "Other Interest": r2(other_interest),
            "EPF Taxable Interest": r2(epf_interest),
        },
        "Gross Total Income": r2(gross_total_income),
        "Deductions": {
            "80C": r2(sec80c),
            "80CCC": r2(sec80ccc),
            "80CCD(1)": r2(sec80ccd1),
            "80CCD(1B)": r2(sec80ccd1b),
            "80CCD(2)": r2(sec80ccd2),
            "80D": r2(sec80d),
            "80E": r2(sec80e),
            "80G": r2(sec80g),
            "80TTA": r2(sec80tta),
            "80TTB": r2(sec80ttb),
            "Total Deductions": r2(total_deductions),
        },
        "Total Taxable Income": r2(total_taxable_income),
        "Tax Computation": {
            "Tax at Slab Rates": r2(tax_slab),
            "Tax on STCG (Section 111A)": r2(tax_stcg_111a),
            "Tax on STCG (Other)": r2(tax_stcg_other),
            "Tax on LTCG (Section 112A)": r2(tax_ltcg_112a),
            "Tax on LTCG (Non-Equity)": r2(tax_ltcg_non_equity),
            "Tax on LTCG (Other)": r2(tax_ltcg_other),
            "Total Tax Before Rebate": r2(total_tax_before_rebate),
            "Less: Rebate under Section 87A": r2(rebate),
            "Tax After Rebate": r2(tax_after_rebate),
            "Surcharge": r2(surcharge),
            "Health and Education Cess": r2(cess),
            "Total Tax Liability": r2(total_tax_liability),
            "Less: TDS": r2(tds),
            "Net Tax Payable / Refund": r2(net_payable),
        },
    }


def compute_tax_output(data):
    regime = str(data.get("Tax Regime") or "new").strip().lower()
    salary = data.get("Gross Salary") or {}
    salary_base = num(salary.get("Basic Salary")) + num(salary.get("Dearness Allowance"))

    hra_exempt = 0.0
    lta_exempt = 0.0
    if regime == "old":
        hra_exempt = hra_exemption(data, salary, salary_base)
        lta_exempt = lta_exemption(data, salary, salary_base)

    output = build_output(data, hra_exempt, lta_exempt)

    # HRA / LTA exemptions are not available where total income exceeds
    # Rs.19,90,000 (FY 2025-26) - recompute without them in that case.
    if regime == "old" and (hra_exempt > 0 or lta_exempt > 0):
        if output["Total Taxable Income"] > HRA_LTA_INCOME_CAP:
            output = build_output(data, 0.0, 0.0)
    return output


def main():
    path = os.path.join(os.getcwd(), "input.json")
    try:
        with open(path, "r", encoding="utf-8") as handle:
            data = json.load(handle)
    except OSError as exc:
        sys.stderr.write("Unable to read input.json: %s\n" % exc)
        return 1
    except ValueError as exc:
        sys.stderr.write("input.json is not valid JSON: %s\n" % exc)
        return 1

    output = compute_tax_output(data)
    sys.stdout.write(json.dumps(output, indent=2, ensure_ascii=False))
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
