Write a Python script that reads the input JSON from the file 'input.json' in the current working directory, computes the tax output, and prints ONLY the output JSON to stdout. You have access to the Python standard library only.

IMPORTANT -- this overrides the output-format instruction in the system prompt above. For this task do NOT reply with the tax JSON itself. Reply with the Python script, wrapped in a ```python code fence. The JSON schema in the system prompt describes what your script must PRINT, not what you should reply with.

```python
#!/usr/bin/env python3
"""
Indian income tax calculator for FY 2025-26 (AY 2026-27).

Reads the taxpayer details from 'input.json' in the current working directory
and prints ONLY the computed tax output (JSON) on stdout.

Rules implemented
-----------------
* The regime given in the input is used as-is (no comparison with the other
  regime).
* New regime (Section 115BAC), FY 2025-26:
    - slabs: 0-4L nil, 4-8L 5%, 8-12L 10%, 12-16L 15%, 16-20L 20%,
      20-24L 25%, above 24L 30%;
    - standard deduction Rs. 75,000 for a salaried individual;
    - rebate u/s 87A: Rs. 60,000 for total income up to Rs. 12,00,000
      (marginal relief above the threshold);
    - Section 10(13A) (HRA) and Section 10(5) (LTA) exemptions are NOT allowed;
    - Chapter VI-A deductions are NOT allowed, except Section 80CCD(2) for
      government employees (the input only distinguishes private/government, so
      'government' is treated as Central Government employment, and the
      employee's own + employer's NPS contribution is allowed within the
      overall limit of 10% of salary or Rs. 1,00,000, whichever is lower);
    - LTCG u/s 112A taxed at 12.5%, STCG u/s 111A at 20%.
* Old regime: standard deduction Rs. 50,000; slabs 0-2.5L nil, 2.5-5L 5%,
  5-10L 20%, above 10L 30%; rebate u/s 87A Rs. 12,500 up to Rs. 5,00,000.
* Section 16(ia) (professional tax, capped at Rs. 2,500) and Section 16(ii)
  (entertainment allowance for government employees) remain available under the
  new regime.  The standard deduction (Section 16(std)) is netted against
  salary because the output schema has no dedicated key for it.
* Capital gains: holding period decides short/long term; losses are set off as
  per Sections 111A(2), 112(3) and 112A(3); the output shows the post-set-off
  (net) figure under each head.
* Health insurance premium paid in cash is not deductible (Section 269B) and
  employer-provided group cover is not deductible.
* Surcharge: 10% (>50L), 15% (>1Cr), 25% (>2Cr), 37% (>5Cr); health &
  education cess 4%.
"""

import json
import os
import sys
from datetime import date

# --------------------------------------------------------------------------
# Statutory parameters - FY 2025-26 (AY 2026-27)
# --------------------------------------------------------------------------
NEW_SLABS = ((400000.0, 0.00), (800000.0, 0.05), (1200000.0, 0.10),
             (1600000.0, 0.15), (2000000.0, 0.20), (2400000.0, 0.25),
             (None, 0.30))
OLD_SLABS = ((250000.0, 0.00), (500000.0, 0.05), (1000000.0, 0.20),
             (None, 0.30))

NEW_STANDARD_DEDUCTION = 75000.0
OLD_STANDARD_DEDUCTION = 50000.0
NEW_REBATE_LIMIT = 1200000.0
NEW_REBATE_MAX = 60000.0
OLD_REBATE_LIMIT = 500000.0
OLD_REBATE_MAX = 12500.0

STCG_111A_RATE = 0.20
LTCG_112A_RATE = 0.125
CESS_RATE = 0.04

CURRENT_FY = "2025-26"
EQUITY_FUND_TYPES = {"equity", "elss", "hybrid-equity"}
FULL_EXEMPT_DONATIONS = ("pm cares", "pm cares fund", "pmjay", "pm jan arogya",
                         "national relief fund", "chief minister's relief fund",
                         "cmrf")


# --------------------------------------------------------------------------
# Small helpers
# --------------------------------------------------------------------------
def to_num(value):
    """Convert any input value to a float (0.0 for missing/blank values)."""
    if value is None or isinstance(value, bool):
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).replace(",", "").replace("Rs.", "").strip()
    if not text:
        return 0.0
    try:
        return float(text)
    except ValueError:
        return 0.0


def parse_date(value):
    if not value:
        return None
    try:
        return date.fromisoformat(str(value)[:10])
    except ValueError:
        return None


def holding_days(purchase, sale):
    if purchase is None or sale is None:
        return 0
    return (sale - purchase).days


def is_long_term(days):
    """A holding period of more than 12 months is long term."""
    return days > 365


def loss_is_usable(financial_year):
    """Capital losses can be carried forward for 8 assessment years."""
    if not financial_year:
        return True
    text = str(financial_year).strip()
    try:
        start_year = int(text.split("-")[0])
    except (ValueError, IndexError):
        return True
    return (start_year + 8) >= int(CURRENT_FY.split("-")[0])


def slab_tax(income, slabs):
    """Tax on `income` using the given slab structure."""
    if income <= 0:
        return 0.0
    tax = 0.0
    lower = 0.0
    for upper, rate in slabs:
        if upper is None:
            tax += (income - lower) * rate
            break
        if income > lower:
            tax += (min(income, upper) - lower) * rate
        if income <= upper:
            break
        lower = upper
    return tax


def rebate_87a(tax, income, regime, slabs):
    """Rebate under Section 87A (with marginal relief just above the cap)."""
    if regime == "new":
        limit, cap = NEW_REBATE_LIMIT, NEW_REBATE_MAX
    else:
        limit, cap = OLD_REBATE_LIMIT, OLD_REBATE_MAX
    if income <= limit:
        return min(cap, tax)
    if tax <= cap:
        return tax
    excess_tax = tax - slab_tax(limit, slabs)
    if excess_tax < cap:
        return max(0.0, cap - excess_tax)
    return 0.0


def surcharge_amount(tax, income, regime):
    if income <= 5000000.0:
        return 0.0
    if income <= 10000000.0:
        rate = 0.10
    elif income <= 20000000.0:
        rate = 0.15
    elif income <= 50000000.0:
        rate = 0.25
    else:
        rate = 0.37
    if regime == "new" and income <= 10000000.0:
        rate = min(rate, 0.15)
    return tax * rate


def absorb_scalar(pool, loss):
    """Use `loss` against a single capital-gain pool; return the unused loss."""
    used = min(pool["amount"], loss)
    pool["amount"] -= used
    return loss - used


def absorb_dict(pool, loss, order):
    """Use `loss` against the sub-heads of a capital-gain pool."""
    for key in order:
        if loss <= 0:
            break
        used = min(pool[key], loss)
        pool[key] -= used
        loss -= used
    return loss


def round_all(obj):
    if isinstance(obj, dict):
        return {key: round_all(value) for key, value in obj.items()}
    if isinstance(obj, list):
        return [round_all(value) for value in obj]
    if isinstance(obj, float):
        value = round(obj, 2)
        return 0.0 if value == 0 else value
    return obj


# --------------------------------------------------------------------------
# Main computation
# --------------------------------------------------------------------------
def compute_tax(data):
    regime = str(data.get("Tax Regime", "new")).strip().lower()
    if regime not in ("old", "new"):
        regime = "new"
    age = to_num(data.get("Age"))
    employment = str(data.get("Employment Type", "private")).strip().lower()
    city = str(data.get("City", "non-metro")).strip().lower()
    is_senior = 60 <= age < 80

    slabs = NEW_SLABS if regime == "new" else OLD_SLABS
    standard_deduction = (NEW_STANDARD_DEDUCTION if regime == "new"
                          else OLD_STANDARD_DEDUCTION)

    # ---------------------------------------------------------------- salary
    salary = data.get("Gross Salary") or {}
    basic = to_num(salary.get("Basic Salary"))
    dearness = to_num(salary.get("Dearness Allowance"))
    hra = to_num(salary.get("HRA"))
    lta = to_num(salary.get("LTA"))
    entertainment = to_num(salary.get("Entertainment Allowance"))
    gross_salary = sum(to_num(value) for value in salary.values())

    # Section 10(13A) - HRA exemption (old regime only)
    hra_exempt = 0.0
    if regime == "old":
        rent = to_num(data.get("Actual Rent Paid"))
        excess_rent = max(0.0, rent - 0.10 * (basic + dearness))
        hra_exempt = min(hra, excess_rent)

    # Section 10(5) - LTA exemption (old regime only)
    lta_exempt = 0.0
    if regime == "old":
        lta_exempt = min(lta, to_num(data.get("LTA Travel Expenses Claimed")))

    # Section 16(ia) - professional tax (allowed under both regimes)
    sec16_ia = min(to_num(data.get("Professional Tax")), 2500.0)

    # Section 16(ii) - entertainment allowance
    if employment == "government":
        # Actual expenses are not given in the input, so the allowance received
        # is treated as the exempt entertainment expenses.
        sec16_ii = entertainment
    else:
        monthly_cap = 3600.0 if city == "metro" else 1800.0
        sec16_ii = min(entertainment, monthly_cap * 12.0)

    # Section 16(iii) - pension / annuity (no such income in the input)
    sec16_iii = 0.0

    net_salary = (gross_salary - hra_exempt - lta_exempt
                  - sec16_ia - sec16_ii - sec16_iii - standard_deduction)

    # --------------------------------------------------------- capital gains
    stcg_111a = {"amount": 0.0}
    stcg_other = {"Bonds": 0.0, "Debentures": 0.0, "G-Secs": 0.0,
                  "Mutual Funds": 0.0}
    stcg_other_extra = 0.0
    ltcg_112a = {"amount": 0.0}
    ltcg_non_equity = {"Bonds": 0.0, "Debentures": 0.0, "G-Secs": 0.0,
                       "Mutual Funds": 0.0}
    ltcg_other = {"amount": 0.0}

    stcg_111a_loss = 0.0
    stcg_other_loss = 0.0
    ltcg_112a_loss = 0.0
    ltcg_other_loss = 0.0

    # Listed / unlisted shares
    for txn in data.get("Stock Sale Transactions") or []:
        qty = to_num(txn.get("Quantity"))
        sale_value = to_num(txn.get("Sale Price")) * qty
        cost_value = to_num(txn.get("Cost Price")) * qty
        charges = to_num(txn.get("Brokerage")) + to_num(txn.get("STT"))
        purchase = parse_date(txn.get("Purchase Date"))
        sale = parse_date(txn.get("Sale Date"))
        if is_long_term(holding_days(purchase, sale)):
            fmv = to_num(txn.get("FMV as of 31 Jan 2018"))
            if purchase is not None and purchase < date(2018, 1, 31) and fmv > 0:
                cost_value = max(cost_value, fmv * qty)
            gain = sale_value - cost_value - charges
            if gain >= 0:
                ltcg_112a["amount"] += gain
            else:
                ltcg_112a_loss += -gain
        else:
            gain = sale_value - cost_value - charges
            if gain >= 0:
                stcg_111a["amount"] += gain
            else:
                stcg_111a_loss += -gain

    # Mutual funds
    for txn in data.get("Mutual Fund Transactions") or []:
        gain = to_num(txn.get("Sale Value")) - to_num(txn.get("Purchase Value"))
        days = holding_days(parse_date(txn.get("Purchase Date")),
                            parse_date(txn.get("Sale Date")))
        equity = str(txn.get("Type", "")).strip().lower() in EQUITY_FUND_TYPES
        if is_long_term(days):
            if equity:
                if gain >= 0:
                    ltcg_112a["amount"] += gain
                else:
                    ltcg_112a_loss += -gain
            else:
                if gain >= 0:
                    ltcg_non_equity["Mutual Funds"] += gain
                else:
                    ltcg_other_loss += -gain
        else:
            if equity:
                if gain >= 0:
                    stcg_111a["amount"] += gain
                else:
                    stcg_111a_loss += -gain
            else:
                if gain >= 0:
                    stcg_other["Mutual Funds"] += gain
                else:
                    stcg_other_loss += -gain

    # Bonds, debentures and G-Secs
    for key in ("Bonds", "Debentures", "G-Secs"):
        asset = data.get(key) or {}
        gain = to_num(asset.get("Sale Amount")) - to_num(asset.get("Purchase Amount"))
        years = to_num(asset.get("Held for duration in years"))
        if years >= 1:
            if gain >= 0:
                ltcg_non_equity[key] += gain
            else:
                ltcg_other_loss += -gain
        else:
            if gain >= 0:
                stcg_other[key] += gain
            else:
                stcg_other_loss += -gain

    # Privately owned vehicle
    vehicle = data.get("Privately Owned Vehicle") or {}
    gain = to_num(vehicle.get("Sale Amount")) - to_num(vehicle.get("Purchase Amount"))
    years = to_num(vehicle.get("Held for duration in years"))
    if gain:
        if years >= 1:
            if gain >= 0:
                ltcg_other["amount"] += gain
            else:
                ltcg_other_loss += -gain
        else:
            if gain >= 0:
                stcg_other_extra += gain
            else:
                stcg_other_loss += -gain

    # Declared capital losses (carry forward of 8 years is allowed)
    for item in data.get("Short Term Capital Loss") or []:
        if loss_is_usable(item.get("Financial Year")):
            stcg_other_loss += to_num(item.get("Loss Amount"))
    for item in data.get("Long Term Capital Loss") or []:
        if loss_is_usable(item.get("Financial Year")):
            ltcg_other_loss += to_num(item.get("Loss Amount"))

    # ------------------------------------------------------- loss set-offs
    order = ("Bonds", "Debentures", "G-Secs", "Mutual Funds")

    # STCG loss u/s 111A against LTCG income - Section 111A(2)
    loss = stcg_111a_loss
    loss = absorb_scalar(ltcg_112a, loss)
    loss = absorb_dict(ltcg_non_equity, loss, order)
    loss = absorb_scalar(ltcg_other, loss)

    # Other STCG loss against STCG gains first, then LTCG gains
    loss = stcg_other_loss
    loss = absorb_scalar(stcg_111a, loss)
    loss = absorb_dict(stcg_other, loss, order)
    loss = absorb_scalar(ltcg_112a, loss)
    loss = absorb_dict(ltcg_non_equity, loss, order)
    loss = absorb_scalar(ltcg_other, loss)

    # LTCG loss u/s 112A against LTCG u/s 112A income only - Section 112A(3)
    loss = ltcg_112a_loss
    loss = absorb_scalar(ltcg_112a, loss)

    # Other LTCG loss against any LTCG income - Section 112(3)
    loss = ltcg_other_loss
    loss = absorb_scalar(ltcg_112a, loss)
    loss = absorb_dict(ltcg_non_equity, loss, order)
    loss = absorb_scalar(ltcg_other, loss)

    stcg_111a_amount = stcg_111a["amount"]
    stcg_other_total = sum(stcg_other.values()) + stcg_other_extra
    ltcg_112a_amount = ltcg_112a["amount"]
    ltcg_non_equity_total = sum(ltcg_non_equity.values())
    ltcg_other_amount = ltcg_other["amount"]
    capital_gains_total = (stcg_111a_amount + stcg_other_total
                           + ltcg_112a_amount + ltcg_non_equity_total
                           + ltcg_other_amount)

    # ------------------------------------------------------ other sources
    savings_interest = to_num(data.get("Savings Bank Interest"))
    deposit_interest = to_num(data.get("Deposit Interest"))
    other_interest = to_num(data.get("Other Interest"))
    epf_interest = to_num(data.get("EPF Taxable Interest"))
    other_sources_total = (savings_interest + deposit_interest
                           + other_interest + epf_interest)

    gross_total_income = net_salary + capital_gains_total + other_sources_total

    # ----------------------------------------------------------- deductions
    deductions = {
        "80C": 0.0,
        "80CCC": 0.0,
        "80CCD(1)": 0.0,
        "80CCD(1B)": 0.0,
        "80CCD(2)": 0.0,
        "80D": 0.0,
        "80E": 0.0,
        "80G": 0.0,
        "80TTA": 0.0,
        "80TTB": 0.0,
    }

    epf = data.get("EPF") or {}
    epf_employee = epf.get("Employee Contribution") or {}
    epf_employee_total = (to_num(epf_employee.get("Deducted from Salary"))
                          + to_num(epf_employee.get("Voluntary")))
    epf_employer = to_num(epf.get("Employer Contribution"))

    nps = data.get("NPS") or {}
    nps_self = to_num(nps.get("Tier-1 Self Contribution"))
    nps_employer = to_num(nps.get("Tier-1 Employer Contribution"))
    nps_tier2 = to_num(nps.get("Tier-2"))

    pension = data.get("Pension Scheme Premium") or {}
    pension_amount = to_num(pension.get("Amount"))
    pension_years = to_num(pension.get("Number of Years Paid"))

    if regime == "new":
        # Only Section 80CCD(2) survives under the new regime, and that too for
        # government (Central Government) employees.
        if employment == "government":
            limit = min(0.10 * gross_salary, 100000.0)
            deductions["80CCD(2)"] = min(nps_self + nps_employer, limit)
    else:
        section_80c = (to_num(data.get("PPF")) + epf_employee_total
                       + to_num(data.get("ELSS")) + to_num(data.get("NSC"))
                       + to_num(data.get("Sukanya Samriddhi Yojana"))
                       + to_num(data.get("SCSS")))
        if pension_years > 1:
            section_80c += pension_amount
        deductions["80C"] = min(section_80c, 150000.0)

        section_80ccd1 = nps_self
        if pension_years == 1:
            section_80ccd1 += pension_amount
        deductions["80CCD(1)"] = min(section_80ccd1, 50000.0)

        section_80ccd1b = max(0.0, nps_self + nps_tier2 - deductions["80CCD(1)"])
        deductions["80CCD(1B)"] = min(section_80ccd1b, 50000.0)

        deductions["80CCD(2)"] = min(epf_employer, 0.10 * gross_salary,
                                     100000.0)

        # Section 80D - health insurance
        total_80d = 0.0
        for policy in data.get("Health Insurance") or []:
            if str(policy.get("Paid By", "")).strip().lower() != "self":
                continue
            if str(policy.get("Payment Mode", "")).strip().lower() == "cash":
                continue  # Section 269B - cash premium not deductible
            purpose = str(policy.get("Payment Purpose", "")).strip().lower()
            beneficiary_age = to_num(policy.get("Beneficiary Age"))
            amount = to_num(policy.get("Amount"))
            if "preventive" in purpose:
                limit = 5000.0 if beneficiary_age >= 60 else 7500.0
            else:
                limit = 37500.0 if beneficiary_age >= 60 else 25000.0
            total_80d += min(amount, limit)
        deductions["80D"] = total_80d

        # Section 80E - education loan interest (allowed for 8 years)
        education = data.get("Education Loan Interest") or {}
        year = int(to_num(education.get("Year of Repayment")))
        if 1 <= year <= 8:
            deductions["80E"] = to_num(education.get("Interest Paid"))

        # Section 80G - donations
        total_80g = 0.0
        for donation in data.get("Donations") or []:
            scheme = str(donation.get("Scheme Name", "")).strip().lower()
            amount = to_num(donation.get("Amount"))
            mode = str(donation.get("Mode", "")).strip().lower()
            if any(key in scheme for key in FULL_EXEMPT_DONATIONS):
                total_80g += amount
            else:
                total_80g += amount * (0.50 if mode == "cash" else 1.00)
        deductions["80G"] = total_80g

        # Section 80TTA / 80TTB
        deductions["80TTA"] = min(savings_interest, 10000.0)
        if is_senior:
            deductions["80TTB"] = min(deposit_interest, 50000.0)

    total_deductions = sum(deductions.values())
    total_taxable_income = gross_total_income - total_deductions

    # ------------------------------------------------------ tax computation
    ordinary_income = total_taxable_income - capital_gains_total

    tax_slab = slab_tax(ordinary_income, slabs)
    tax_stcg_111a = (STCG_111A_RATE * stcg_111a_amount
                     if stcg_111a_amount > 0 else 0.0)
    tax_stcg_other = (slab_tax(ordinary_income + stcg_other_total, slabs)
                      - tax_slab)
    tax_ltcg_112a = (LTCG_112A_RATE * ltcg_112a_amount
                     if ltcg_112a_amount > 0 else 0.0)
    base = ordinary_income + stcg_other_total
    tax_ltcg_non_equity = (slab_tax(base + ltcg_non_equity_total, slabs)
                           - slab_tax(base, slabs))
    base2 = base + ltcg_non_equity_total
    tax_ltcg_other = (slab_tax(base2 + ltcg_other_amount, slabs)
                      - slab_tax(base2, slabs))

    total_tax_before_rebate = (tax_slab + tax_stcg_111a + tax_stcg_other
                               + tax_ltcg_112a + tax_ltcg_non_equity
                               + tax_ltcg_other)

    rebate = rebate_87a(total_tax_before_rebate, total_taxable_income,
                        regime, slabs)
    tax_after_rebate = total_tax_before_rebate - rebate
    surcharge = surcharge_amount(tax_after_rebate, total_taxable_income, regime)
    cess = CESS_RATE * (tax_after_rebate + surcharge)
    total_tax_liability = tax_after_rebate + surcharge + cess
    tds = to_num(data.get("TDS"))
    net_tax = total_tax_liability - tds

    # ------------------------------------------------------------- output
    output = {
        "Under Head Salaries": {
            "Gross Salary": gross_salary,
            "Exemptions": {
                "Section 10(13A)": hra_exempt,
                "Section 10(5)": lta_exempt,
            },
            "Section 16(ia)": sec16_ia,
            "Section 16(ii)": sec16_ii,
            "Section 16(iii)": sec16_iii,
            "Net Salary": net_salary,
        },
        "Capital Gains": {
            "STCG (Section 111A)": stcg_111a_amount,
            "STCG (Other)": {
                "Bonds": stcg_other["Bonds"],
                "Debentures": stcg_other["Debentures"],
                "G-Secs": stcg_other["G-Secs"],
                "Mutual Funds": stcg_other["Mutual Funds"],
                "Total": stcg_other_total,
            },
            "LTCG (Section 112A)": ltcg_112a_amount,
            "LTCG (Non-Equity)": {
                "Bonds": ltcg_non_equity["Bonds"],
                "Debentures": ltcg_non_equity["Debentures"],
                "G-Secs": ltcg_non_equity["G-Secs"],
                "Mutual Funds": ltcg_non_equity["Mutual Funds"],
                "Total": ltcg_non_equity_total,
            },
            "LTCG (Other)": ltcg_other_amount,
        },
        "Income from Other Sources": {
            "Savings Bank Interest": savings_interest,
            "Deposit Interest": deposit_interest,
            "Other Interest": other_interest,
            "EPF Taxable Interest": epf_interest,
        },
        "Gross Total Income": gross_total_income,
        "Deductions": {
            "80C": deductions["80C"],
            "80CCC": deductions["80CCC"],
            "80CCD(1)": deductions["80CCD(1)"],
            "80CCD(1B)": deductions["80CCD(1B)"],
            "80CCD(2)": deductions["80CCD(2)"],
            "80D": deductions["80D"],
            "80E": deductions["80E"],
            "80G": deductions["80G"],
            "80TTA": deductions["80TTA"],
            "80TTB": deductions["80TTB"],
            "Total Deductions": total_deductions,
        },
        "Total Taxable Income": total_taxable_income,
        "Tax Computation": {
            "Tax at Slab Rates": tax_slab,
            "Tax on STCG (Section 111A)": tax_stcg_111a,
            "Tax on STCG (Other)": tax_stcg_other,
            "Tax on LTCG (Section 112A)": tax_ltcg_112a,
            "Tax on LTCG (Non-Equity)": tax_ltcg_non_equity,
            "Tax on LTCG (Other)": tax_ltcg_other,
            "Total Tax Before Rebate": total_tax_before_rebate,
            "Less: Rebate under Section 87A": rebate,
            "Tax After Rebate": tax_after_rebate,
            "Surcharge": surcharge,
            "Health and Education Cess": cess,
            "Total Tax Liability": total_tax_liability,
            "Less: TDS": tds,
            "Net Tax Payable / Refund": net_tax,
        },
    }
    return round_all(output)


def main():
    path = os.path.join(os.getcwd(), "input.json")
    if not os.path.exists(path):
        path = "input.json"
    with open(path, "r", encoding="utf-8") as handle:
        data = json.load(handle)
    result = compute_tax(data)
    json.dump(result, sys.stdout, indent=2, ensure_ascii=False)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
