```python
#!/usr/bin/env python3
"""Indian income tax calculator — FY 2025-26 (AY 2026-27).

Reads taxpayer details from 'input.json' in the current working directory,
computes the complete tax summary and prints ONLY the resulting JSON to stdout.
Standard library only.
"""

import json
import sys
from datetime import date, datetime

# ---------------------------------------------------------------------------
# Constants for FY 2025-26 (AY 2026-27)
# ---------------------------------------------------------------------------
FY_START_YEAR = 2025                 # FY 2025-26
LOSS_CARRY_FORWARD_YEARS = 8         # capital loss carry forward window

NEW_REGIME_SLABS = [
    (400000.0, 0.00), (800000.0, 0.05), (1200000.0, 0.10),
    (1600000.0, 0.15), (2000000.0, 0.20), (2400000.0, 0.25),
    (float("inf"), 0.30),
]
OLD_REGIME_SLABS = [
    (250000.0, 0.00), (500000.0, 0.05), (1000000.0, 0.20),
    (float("inf"), 0.30),
]
OLD_REGIME_SENIOR_SLABS = [
    (300000.0, 0.00), (500000.0, 0.05), (1000000.0, 0.20),
    (float("inf"), 0.30),
]
OLD_REGIME_SUPER_SENIOR_SLABS = [
    (500000.0, 0.00), (1000000.0, 0.20), (float("inf"), 0.30),
]

STCG_111A_RATE = 0.20                # short term equity / equity MF
LTCG_112A_RATE = 0.125               # long term equity / equity MF (no indexation)

LIMIT_80C = 150000.0
LIMIT_80CCC = 150000.0
LIMIT_80CCD1 = 150000.0
LIMIT_80CCD1B = 50000.0
LIMIT_80D_SELF = 25000.0
LIMIT_80D_SENIOR = 50000.0
LIMIT_80TTA = 10000.0
LIMIT_80TTB = 50000.0
LIMIT_16IA = 150000.0
LIMIT_16II = 100000.0
LIMIT_16III = 2500.0

EQUITY_MF_TYPES = {"equity", "elss", "hybrid-equity"}


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def to_num(value):
    """Best effort conversion of an input value to a float."""
    if isinstance(value, bool):
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        cleaned = value.strip().replace(",", "").replace("₹", "")
        if not cleaned:
            return 0.0
        try:
            return float(cleaned)
        except ValueError:
            return 0.0
    return 0.0


def r2(value):
    """Round to 2 decimals, avoiding float noise in the JSON output."""
    return round(float(value) + 0.0, 2)


def parse_date(value):
    """Parse a date string into a datetime.date (returns None on failure)."""
    if value is None:
        return None
    if isinstance(value, date) and not isinstance(value, datetime):
        return value
    if isinstance(value, datetime):
        return date(value.year, value.month, value.day)
    text = str(value).strip()
    if not text:
        return None
    formats = (
        "%Y-%m-%d", "%d-%m-%Y", "%d/%m/%Y", "%Y/%m/%d",
        "%d-%b-%Y", "%d-%B-%Y", "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M",
    )
    for fmt in formats:
        try:
            parsed = datetime.strptime(text, fmt)
            return date(parsed.year, parsed.month, parsed.day)
        except ValueError:
            continue
    # Fallback: try the leading ISO date portion of a longer timestamp string
    try:
        parsed = datetime.strptime(text[:10], "%Y-%m-%d")
        return date(parsed.year, parsed.month, parsed.day)
    except ValueError:
        return None


def is_long_term(purchase, sale):
    """More than 12 months of holding => long term capital asset."""
    if purchase is None or sale is None:
        return False
    return (sale - purchase).days > 365


def fy_start_year(fy):
    if fy is None:
        return None
    text = str(fy).strip()
    if not text:
        return None
    try:
        return int(text.split("-")[0].split("/")[0])
    except ValueError:
        return None


def loss_is_set_offtable(fy):
    """A capital loss can be set off in FY 2025-26 only if it is not older
    than the 8 year carry forward window (loss FY 2017-18 onwards)."""
    year = fy_start_year(fy)
    if year is None:
        return True
    if year > FY_START_YEAR:
        return False
    return year + LOSS_CARRY_FORWARD_YEARS >= FY_START_YEAR


def slab_tax(income, slabs):
    """Tax on `income` using the given (upper limit, rate) slab structure."""
    if income <= 0:
        return 0.0
    tax = 0.0
    lower = 0.0
    for upper, rate in slabs:
        if income <= lower:
            break
        taxable = min(income, upper) - lower
        tax += taxable * rate
        lower = upper
    return tax


# ---------------------------------------------------------------------------
# Core computation
# ---------------------------------------------------------------------------
def compute_tax(data):
    age = to_num(data.get("Age"))
    employment = str(data.get("Employment Type", "private")).strip().lower()
    regime = str(data.get("Tax Regime", "new")).strip().lower()
    city = str(data.get("City", "non-metro")).strip().lower()
    is_metro = city.startswith("metro")
    is_new_regime = regime.startswith("new")

    # ---------------- Salaries -------------------------------------------
    salary = data.get("Gross Salary") or {}
    basic = to_num(salary.get("Basic Salary"))
    da = to_num(salary.get("Dearness Allowance"))
    hra = to_num(salary.get("HRA"))
    lta = to_num(salary.get("LTA"))
    gross_salary = sum(to_num(v) for v in salary.values())
    salary_for_exempt = basic + da

    # HRA exemption - least of (a) HRA received, (b) rent - 10% of salary,
    # (c) 50% of salary (metro) / 40% (non-metro)
    rent_paid = to_num(data.get("Actual Rent Paid"))
    hra_exempt = 0.0
    if hra > 0 and rent_paid > 0:
        pct = 0.50 if is_metro else 0.40
        hra_exempt = max(0.0, min(hra,
                                  rent_paid - 0.10 * salary_for_exempt,
                                  pct * salary_for_exempt))

    # LTA exemption - least of (a) LTA received, (b) actual travel expenses
    # claimed, (c) 5% of salary (metro) / 3% (non-metro)
    travel_claimed = to_num(data.get("LTA Travel Expenses Claimed"))
    lta_exempt = 0.0
    if lta > 0:
        pct = 0.05 if is_metro else 0.03
        lta_exempt = max(0.0, min(lta, travel_claimed, pct * salary_for_exempt))

    epf = data.get("EPF") or {}
    employee_contrib = epf.get("Employee Contribution") or {}
    employer_epf = to_num(epf.get("Employer Contribution"))
    nps = data.get("NPS") or {}
    nps_self = to_num(nps.get("Tier-1 Self Contribution"))
    nps_employer = to_num(nps.get("Tier-1 Employer Contribution"))

    sec16ia = min(employer_epf, LIMIT_16IA)
    sec16ii = min(nps_employer, LIMIT_16II)
    sec16iii = min(to_num(data.get("Professional Tax")), LIMIT_16III)

    net_salary = (gross_salary - hra_exempt - lta_exempt
                  - sec16ia - sec16ii - sec16iii)

    # ---------------- Capital gains -------------------------------------
    stcg_111a = 0.0
    ltcg_112a = 0.0
    ltcg_other = 0.0
    stcg_other = {"Bonds": 0.0, "Debentures": 0.0, "G-Secs": 0.0, "Mutual Funds": 0.0}
    ltcg_non_equity = {"Bonds": 0.0, "Debentures": 0.0, "G-Secs": 0.0, "Mutual Funds": 0.0}
    stcg_loss_current = 0.0
    ltcg_loss_current = 0.0

    # Listed equity shares (STT / FMV style transactions)
    for txn in data.get("Stock Sale Transactions") or []:
        qty = to_num(txn.get("Quantity"))
        sale_value = to_num(txn.get("Sale Price")) * qty
        cost_value = to_num(txn.get("Cost Price")) * qty
        gain = (sale_value - cost_value
                - to_num(txn.get("Brokerage")) - to_num(txn.get("STT")))
        long_term = is_long_term(parse_date(txn.get("Purchase Date")),
                                 parse_date(txn.get("Sale Date")))
        if gain >= 0:
            if long_term:
                ltcg_112a += gain
            else:
                stcg_111a += gain
        else:
            if long_term:
                ltcg_loss_current += -gain
            else:
                stcg_loss_current += -gain

    # Mutual fund transactions
    for txn in data.get("Mutual Fund Transactions") or []:
        fund_type = str(txn.get("Type", "")).strip().lower()
        gain = to_num(txn.get("Sale Value")) - to_num(txn.get("Purchase Value"))
        long_term = is_long_term(parse_date(txn.get("Purchase Date")),
                                 parse_date(txn.get("Sale Date")))
        if fund_type in EQUITY_MF_TYPES:
            if gain >= 0:
                if long_term:
                    ltcg_112a += gain
                else:
                    stcg_111a += gain
            else:
                if long_term:
                    ltcg_loss_current += -gain
                else:
                    stcg_loss_current += -gain
        else:
            if gain >= 0:
                if long_term:
                    ltcg_non_equity["Mutual Funds"] += gain
                else:
                    stcg_other["Mutual Funds"] += gain
            else:
                if long_term:
                    ltcg_loss_current += -gain
                else:
                    stcg_loss_current += -gain

    # Bonds / Debentures / G-Secs
    for key in ("Bonds", "Debentures", "G-Secs"):
        asset = data.get(key) or {}
        gain = to_num(asset.get("Sale Amount")) - to_num(asset.get("Purchase Amount"))
        long_term = to_num(asset.get("Held for duration in years")) > 1
        if gain >= 0:
            if long_term:
                ltcg_non_equity[key] += gain
            else:
                stcg_other[key] += gain
        else:
            if long_term:
                ltcg_loss_current += -gain
            else:
                stcg_loss_current += -gain

    # Declared capital losses (subject to the 8 year carry forward window)
    stcg_loss_pool = stcg_loss_current
    for entry in data.get("Short Term Capital Loss") or []:
        if loss_is_set_offtable(entry.get("Financial Year")):
            stcg_loss_pool += to_num(entry.get("Loss Amount"))

    ltcg_loss_pool = ltcg_loss_current
    for entry in data.get("Long Term Capital Loss") or []:
        if loss_is_set_offtable(entry.get("Financial Year")):
            ltcg_loss_pool += to_num(entry.get("Loss Amount"))

    # Set off STCG losses against STCG gains
    remaining_stcg = stcg_loss_pool
    if remaining_stcg > 0:
        used = min(remaining_stcg, stcg_111a)
        stcg_111a -= used
        remaining_stcg -= used
    if remaining_stcg > 0:
        for key in ("Bonds", "Debentures", "G-Secs", "Mutual Funds"):
            used = min(remaining_stcg, stcg_other[key])
            stcg_other[key] -= used
            remaining_stcg -= used
            if remaining_stcg <= 0:
                break

    # Set off LTCG losses against LTCG gains
    remaining_ltcg = ltcg_loss_pool
    if remaining_ltcg > 0:
        used = min(remaining_ltcg, ltcg_112a)
        ltcg_112a -= used
        remaining_ltcg -= used
    if remaining_ltcg > 0:
        for key in ("Bonds", "Debentures", "G-Secs", "Mutual Funds"):
            used = min(remaining_ltcg, ltcg_non_equity[key])
            ltcg_non_equity[key] -= used
            remaining_ltcg -= used
            if remaining_ltcg <= 0:
                break
    if remaining_ltcg > 0:
        used = min(remaining_ltcg, ltcg_other)
        ltcg_other -= used
        remaining_ltcg -= used

    # Old regime: cross set off of residual losses
    if not is_new_regime:
        if remaining_stcg > 0:
            used = min(remaining_stcg, ltcg_112a)
            ltcg_112a -= used
            remaining_stcg -= used
        if remaining_stcg > 0:
            for key in ("Bonds", "Debentures", "G-Secs", "Mutual Funds"):
                used = min(remaining_stcg, ltcg_non_equity[key])
                ltcg_non_equity[key] -= used
                remaining_stcg -= used
                if remaining_stcg <= 0:
                    break
        if remaining_stcg > 0:
            used = min(remaining_stcg, ltcg_other)
            ltcg_other -= used
            remaining_stcg -= used
        if remaining_ltcg > 0:
            used = min(remaining_ltcg, stcg_111a)
            stcg_111a -= used
            remaining_ltcg -= used
        if remaining_ltcg > 0:
            for key in ("Bonds", "Debentures", "G-Secs", "Mutual Funds"):
                used = min(remaining_ltcg, stcg_other[key])
                stcg_other[key] -= used
                remaining_ltcg -= used
                if remaining_ltcg <= 0:
                    break

    stcg_other_total = sum(stcg_other.values())
    ltcg_non_equity_total = sum(ltcg_non_equity.values())

    # ---------------- Income from other sources --------------------------
    savings_interest = to_num(data.get("Savings Bank Interest"))
    deposit_interest = to_num(data.get("Deposit Interest"))
    other_interest = to_num(data.get("Other Interest"))
    epf_interest = to_num(data.get("EPF Taxable Interest"))

    gross_total_income = (net_salary + stcg_111a + stcg_other_total
                          + ltcg_112a + ltcg_non_equity_total + ltcg_other
                          + savings_interest + deposit_interest
                          + other_interest + epf_interest)

    # ---------------- Deductions -----------------------------------------
    sec80c = sec80ccc = sec80ccd1 = sec80ccd1b = sec80ccd2 = 0.0
    sec80d = sec80e = sec80g = sec80tta = sec80ttb = 0.0

    if not is_new_regime:
        # 80C
        epf_employee = (to_num(employee_contrib.get("Deducted from Salary"))
                        + to_num(employee_contrib.get("Voluntary")))
        sec80c = min(LIMIT_80C,
                     to_num(data.get("PPF")) + epf_employee
                     + to_num(data.get("ELSS")) + to_num(data.get("NSC"))
                     + to_num(data.get("Sukanya Samriddhi Yojana"))
                     + to_num(data.get("SCSS")))

        # 80CCC - pension scheme premium (multi year premium spread evenly)
        pension = data.get("Pension Scheme Premium") or {}
        pension_amount = to_num(pension.get("Amount"))
        pension_years = to_num(pension.get("Number of Years Paid"))
        if pension_years > 1:
            pension_amount = pension_amount / pension_years
        sec80ccc = min(LIMIT_80CCC, pension_amount)

        # 80CCD(1) and 80CCD(1B)
        sec80ccd1 = min(LIMIT_80CCD1, nps_self)
        sec80ccd1b = min(LIMIT_80CCD1B, max(0.0, nps_self - sec80ccd1))

        # 80CCD(2) - employer's NPS contribution (not allowed if 80CCD(1)/(1B))
        if sec80ccd1 > 0 or sec80ccd1b > 0:
            sec80ccd2 = 0.0
        else:
            sec80ccd2 = min(nps_employer, 0.10 * (basic + da))

        # 80D - health insurance premium paid by the assessee
        eligible_premium = 0.0
        for policy in data.get("Health Insurance") or []:
            paid_by = str(policy.get("Paid By", "")).strip().lower()
            if paid_by != "self":
                continue                      # employer / group cover: not allowed
            years = to_num(policy.get("Number of Years Paid"))
            amount = to_num(policy.get("Amount"))
            if years > 1:
                amount = amount / years
            beneficiary = str(policy.get("Beneficiary", "")).strip().lower()
            if beneficiary in ("self", "spouse", "children", "child",
                               "son", "daughter", "parents", "parent"):
                eligible_premium += amount
        sec80d = min(LIMIT_80D_SENIOR if age >= 60 else LIMIT_80D_SELF,
                     eligible_premium)

        # 80E - education loan interest (allowed for 8 consecutive years)
        education = data.get("Education Loan Interest") or {}
        repayment_year = to_num(education.get("Year of Repayment"))
        if 1 <= repayment_year <= 8:
            sec80e = to_num(education.get("Interest Paid"))

        # 80G - donations
        for donation in data.get("Donations") or []:
            scheme = str(donation.get("Scheme Name", "")).strip().lower()
            amount = to_num(donation.get("Amount"))
            if ("pm cares" in scheme or "drought relief" in scheme
                    or "national relief" in scheme):
                sec80g += amount
            else:
                sec80g += 0.50 * amount

        # 80TTA / 80TTB
        sec80tta = min(LIMIT_80TTA, savings_interest)
        if age >= 60:
            sec80ttb = min(LIMIT_80TTB, deposit_interest)

    total_deductions = (sec80c + sec80ccc + sec80ccd1 + sec80ccd1b + sec80ccd2
                        + sec80d + sec80e + sec80g + sec80tta + sec80ttb)

    total_taxable_income = max(0.0, gross_total_income - total_deductions)

    # ---------------- Tax computation ------------------------------------
    salaried = gross_salary > 0
    if is_new_regime:
        standard_deduction = 75000.0
        slabs = NEW_REGIME_SLABS
    else:
        standard_deduction = 50000.0 if salaried else 0.0
        if age >= 80:
            slabs = OLD_REGIME_SUPER_SENIOR_SLABS
        elif age >= 60:
            slabs = OLD_REGIME_SENIOR_SLABS
        else:
            slabs = OLD_REGIME_SLABS

    income_after_std = max(0.0, total_taxable_income - standard_deduction)

    total_cg = (stcg_111a + stcg_other_total + ltcg_112a
                + ltcg_non_equity_total + ltcg_other)
    slab_base = max(0.0, income_after_std - total_cg)

    tax_slab = slab_tax(slab_base, slabs)
    tax_stcg_111a = STCG_111A_RATE * stcg_111a
    tax_stcg_other = slab_tax(stcg_other_total, slabs)
    tax_ltcg_112a = LTCG_112A_RATE * ltcg_112a
    tax_ltcg_non_equity = slab_tax(ltcg_non_equity_total, slabs)
    tax_ltcg_other = slab_tax(ltcg_other, slabs)

    total_tax_before_rebate = (tax_slab + tax_stcg_111a + tax_stcg_other
                               + tax_ltcg_112a + tax_ltcg_non_equity
                               + tax_ltcg_other)

    # Rebate under section 87A
    if is_new_regime:
        rebate_income_limit, rebate_cap = 1200000.0, 60000.0
    else:
        rebate_income_limit, rebate_cap = 500000.0, 12500.0
    if income_after_std <= rebate_income_limit:
        rebate = min(total_tax_before_rebate, rebate_cap)
    else:
        rebate = 0.0
    tax_after_rebate = total_tax_before_rebate - rebate

    # Surcharge
    surcharge = 0.0
    if total_taxable_income > 5000000.0:
        if is_new_regime:
            if total_taxable_income > 20000000.0:
                surcharge_rate = 0.25
            elif total_taxable_income > 10000000.0:
                surcharge_rate = 0.15
            else:
                surcharge_rate = 0.10
        else:
            if total_taxable_income > 50000000.0:
                surcharge_rate = 0.37
            elif total_taxable_income > 20000000.0:
                surcharge_rate = 0.25
            elif total_taxable_income > 10000000.0:
                surcharge_rate = 0.15
            else:
                surcharge_rate = 0.10
        surcharge = tax_after_rebate * surcharge_rate
        # surcharge on capital gains income (111A / 112A) capped at 15%
        cg_tax = tax_stcg_111a + tax_ltcg_112a
        if cg_tax > 0 and surcharge_rate > 0.15 and tax_after_rebate > 0:
            attributable = surcharge * (cg_tax / tax_after_rebate)
            cap = 0.15 * cg_tax
            if attributable > cap:
                surcharge -= (attributable - cap)

    cess = 0.04 * (tax_after_rebate + surcharge)
    total_tax_liability = tax_after_rebate + surcharge + cess

    tds = to_num(data.get("TDS"))
    net_tax = total_tax_liability - tds

    # ---------------- Output ---------------------------------------------
    return {
        "Under Head Salaries": {
            "Gross Salary": r2(gross_salary),
            "Exemptions": {
                "Section 10(13A)": r2(hra_exempt),
                "Section 10(5)": r2(lta_exempt),
            },
            "Section 16(ia)": r2(sec16ia),
            "Section 16(ii)": r2(sec16ii),
            "Section 16(iii)": r2(sec16iii),
            "Net Salary": r2(net_salary),
        },
        "Capital Gains": {
            "STCG (Section 111A)": r2(stcg_111a),
            "STCG (Other)": {
                "Bonds": r2(stcg_other["Bonds"]),
                "Debentures": r2(stcg_other["Debentures"]),
                "G-Secs": r2(stcg_other["G-Secs"]),
                "Mutual Funds": r2(stcg_other["Mutual Funds"]),
                "Total": r2(stcg_other_total),
            },
            "LTCG (Section 112A)": r2(ltcg_112a),
            "LTCG (Non-Equity)": {
                "Bonds": r2(ltcg_non_equity["Bonds"]),
                "Debentures": r2(ltcg_non_equity["Debentures"]),
                "G-Secs": r2(ltcg_non_equity["G-Secs"]),
                "Mutual Funds": r2(ltcg_non_equity["Mutual Funds"]),
                "Total": r2(ltcg_non_equity_total),
            },
            "LTCG (Other)": r2(ltcg_other),
        },
        "Income from Other Sources": {
            "Savings Bank Interest": r2(savings_interest),
            "Deposit Interest": r2(deposit_interest),
            "Other Interest": r2(other_interest),
            "EPF Taxable Interest": r2(epf_interest),
        },
        "Gross Total Income": r2(gross_total_income),
        "Deductions": {
            "80C": r2(sec80c),
            "80CCC": r2(sec80ccc),
            "80CCD(1)": r2(sec80ccd1),
            "80CCD(1B)": r2(sec80ccd1b),
            "80CCD(2)": r2(sec80ccd2),
            "80D": r2(sec80d),
            "80E": r2(sec80e),
            "80G": r2(sec80g),
            "80TTA": r2(sec80tta),
            "80TTB": r2(sec80ttb),
            "Total Deductions": r2(total_deductions),
        },
        "Total Taxable Income": r2(total_taxable_income),
        "Tax Computation": {
            "Tax at Slab Rates": r2(tax_slab),
            "Tax on STCG (Section 111A)": r2(tax_stcg_111a),
            "Tax on STCG (Other)": r2(tax_stcg_other),
            "Tax on LTCG (Section 112A)": r2(tax_ltcg_112a),
            "Tax on LTCG (Non-Equity)": r2(tax_ltcg_non_equity),
            "Tax on LTCG (Other)": r2(tax_ltcg_other),
            "Total Tax Before Rebate": r2(total_tax_before_rebate),
            "Less: Rebate under Section 87A": r2(rebate),
            "Tax After Rebate": r2(tax_after_rebate),
            "Surcharge": r2(surcharge),
            "Health and Education Cess": r2(cess),
            "Total Tax Liability": r2(total_tax_liability),
            "Less: TDS": r2(tds),
            "Net Tax Payable / Refund": r2(net_tax),
        },
    }


def main():
    try:
        with open("input.json", "r", encoding="utf-8") as handle:
            data = json.load(handle)
    except OSError as exc:
        print("Unable to read input.json: %s" % exc, file=sys.stderr)
        return 1
    except json.JSONDecodeError as exc:
        print("input.json is not valid JSON: %s" % exc, file=sys.stderr)
        return 1

    result = compute_tax(data)
    json.dump(result, sys.stdout, indent=2)
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
